    pub(crate) fn is_enabled(&self, format: ForeignInstructionFormat) -> bool {
        self.enabled.contains(format.key())
    }

    #[must_use]
    pub(crate) fn is_empty(&self) -> bool {
        self.enabled.is_empty()
    }

