"""Minimal ANSI grid emulator with correct combining-mark handling.

pyte places every codepoint in its own cell, which shreds Devanagari (and any
script that builds graphemes from combining marks) into unreadable output. Here
a combining mark is appended to the cell that precedes it, and a wide character
occupies two cells, so the reconstructed frame matches what a real terminal
shows.
"""
import re, unicodedata

CSI = re.compile(r'\x1b\[([0-9;?]*)([@-~])')
OSC = re.compile(r'\x1b\][^\x07\x1b]*(?:\x07|\x1b\\)')
ESC_OTHER = re.compile(r'\x1b[()][B0]|\x1b[=><]|\x1b[MDE78]')

def is_combining(ch):
    return unicodedata.combining(ch) != 0 or unicodedata.category(ch) in ("Mn", "Me")

def char_width(ch):
    return 2 if unicodedata.east_asian_width(ch) in ("W", "F") else 1

class Grid:
    def __init__(self, cols=120, rows=32):
        self.cols, self.rows = cols, rows
        self.buf = [[" "] * cols for _ in range(rows)]
        self.cy = self.cx = 0

    def _clamp(self):
        self.cy = max(0, min(self.rows - 1, self.cy))
        self.cx = max(0, min(self.cols - 1, self.cx))

    def put(self, ch):
        if is_combining(ch):
            x = self.cx - 1
            while x >= 0 and self.buf[self.cy][x] == "":
                x -= 1
            if x >= 0:
                self.buf[self.cy][x] += ch
            return
        w = char_width(ch)
        if self.cx + w > self.cols:
            self.cx = 0
            self.cy = min(self.cy + 1, self.rows - 1)
        self.buf[self.cy][self.cx] = ch
        if w == 2 and self.cx + 1 < self.cols:
            self.buf[self.cy][self.cx + 1] = ""
        self.cx += w

    def erase_line(self, mode):
        row = self.buf[self.cy]
        if mode == 0:
            for x in range(self.cx, self.cols): row[x] = " "
        elif mode == 1:
            for x in range(0, min(self.cx + 1, self.cols)): row[x] = " "
        else:
            for x in range(self.cols): row[x] = " "

    def erase_display(self, mode):
        if mode == 2 or mode == 3:
            self.buf = [[" "] * self.cols for _ in range(self.rows)]
            self.cy = self.cx = 0
        elif mode == 0:
            self.erase_line(0)
            for y in range(self.cy + 1, self.rows):
                self.buf[y] = [" "] * self.cols
        else:
            self.erase_line(1)
            for y in range(0, self.cy):
                self.buf[y] = [" "] * self.cols

    def feed(self, text):
        i = 0
        while i < len(text):
            ch = text[i]
            if ch == "\x1b":
                m = CSI.match(text, i)
                if m:
                    self._csi(m.group(1), m.group(2)); i = m.end(); continue
                m = OSC.match(text, i)
                if m: i = m.end(); continue
                m = ESC_OTHER.match(text, i)
