    if previous == current {
        return None;
    }
    // Both sides must parse for the comparison to mean anything. A version we
    // cannot order is a version we cannot claim moved forward.
    let (Ok(before), Ok(now)) = (Version::parse(previous), Version::parse(current)) else {
